### Description

See: https://github.com/projectcalico/calico/issues/9527#issuecomment-2529876206

Add a preflight check in kyverno cleanup controller to not start metadata informers if forbidden error is returned, for example:

```
func (m *managerWithErrorHandling) preflightCheck(
	ctx context.Context,
	gvr schema.GroupVersionResource,
	logger logr.Logger,
) error {
	opts := metav1.ListOptions{
		LabelSelector: kyverno.LabelCleanupTtl,
		Limit:         1,
	}

	_, err := m.metadataClient.Resource(gvr).List(ctx, opts)
	if err != nil {
		// Check if it's a 403 Forbidden
		if apierrors.IsForbidden(err) {
			return fmt.Errorf("preflight authorization check failed: %w", err)
		}
		// For other errors (like NotFound), we might still want to proceed
		// as the resource type might exist but just have no items
		if !apierrors.IsNotFound(err) {
			return fmt.Errorf("preflight check failed: %w", err)
		}
	}

	return nil
}
```

